# Please run the file from its directory or modify the paths
current_dir = os.getcwd()
project_dir = os.path.abspath(os.path.join(current_dir, os.pardir, os.pardir))
parent_dir = os.path.abspath(os.path.join(project_dir, os.pardir))

is_old_results = False
is_top_k_gt = True

# for writing results to csv (from root dir of the project)
results_dir = f"{project_dir}/results/plan_recovery/final_evaluation_old" if is_old_results else f"{project_dir}/results/plan_recovery/final_evaluation"
results_dir = results_dir if is_top_k_gt else f"{results_dir}_optimal_gt"
tmp_outputs_dir = f"{project_dir}/results/plan_recovery/tmp_outputs/"
plans_dir = f"{current_dir}/plans"

os.makedirs(results_dir, exist_ok=True)
os.makedirs(tmp_outputs_dir, exist_ok=True)
os.makedirs(plans_dir, exist_ok=True)

dict_lock = threading.Lock()
_instances_since_save = 0

def limit_memory(max_mb: int = 1500):
    try:
        soft, hard = resource.getrlimit(resource.RLIMIT_AS)
        max_bytes = max_mb * 1024 * 1024
        resource.setrlimit(resource.RLIMIT_DATA, (max_bytes, hard))
    except Exception as e:
        print(f"Failed to set memory limit: {e}")

def profile_process_instance(instance, task, domain, model, params, search_params):
    # profiler = cProfile.Profile()
    # profiler.enable()
    global _instances_since_save

    try:
        result = process_instance(instance, task, domain, model, params, search_params)
        _instances_since_save += 1
        if _instances_since_save >= 5:
            save_worker_caches()
            _instances_since_save = 0

        return result
    finally:
        # profiler.disable()

        # os.makedirs("profiles", exist_ok=True)
        # inst_num = instance.get("instance_id")
        # profiler.dump_stats(f"profiles/instance_{inst_num}_pid{os.getpid()}.prof")
        pass


def process_instance(instance, task, domain, model, params, search_params) -> tuple[int, bool, str, list]:
    inst_num = instance.get("instance_id")
    llm_plan = instance.get("extracted_llm_plan")
    optimal_gt_plan = instance.get("ground_truth_plan")
    validity = instance.get("llm_correct")
    print(f"Processing instance {inst_num}")

    # default_values = [model, domain, task, inst_num, "GT plan missing", "LLM plan missing", "Plan trace missing", "NR Plan trace missing", "Trace score missing", "Complementary plan missing", "Correct part missing", "Executability missing"]
    default_values: list = [model, domain, task, inst_num]

    if "pddl" in task and optimal_gt_plan is not None:  # For PDDL task GT has cost in the last line
        # print(f"DEBUG: there is an optimal plan in PDDL plans")
        optimal_gt_plan = "\n".join(optimal_gt_plan.rstrip("\n").rsplit("\n", 1)[:-1]) + "\n"
    elif optimal_gt_plan is not None:
        # print(f"DEBUG: there is an optimal plan in non-PDDL plans")
        optimal_gt_plan = optimal_gt_plan
    else:
        # print(f"DEBUG: Instance {inst_num} of domain {domain} has missing optimal GT plan, taking first plan from GT plans")
        gt_plans = get_gt_plans(domain, inst_num)
        if gt_plans and "pddl" in task:
            optimal_gt_plan = gt_plans[0]
        elif gt_plans:
            optimal_gt_plan = "\n".join(gt_plans[0].rstrip("\n").rsplit("\n", 1)[:-1]) + "\n"

    # default_values += get_default_values_for_csv(optimal_gt_plan)
    default_values.extend(get_default_values_for_csv(optimal_gt_plan))

    if llm_plan is None:
        print(f"Instance {inst_num} has missing plan, skipping evaluation.")
        return inst_num, False, "LLM plan missing", default_values
    elif optimal_gt_plan is None:
        print(f"No GT plans found for instance {inst_num} in domain {domain}. Skipping evaluation.")
        default_values.extend(get_default_values_for_csv(optimal_gt_plan))
        return inst_num, False, "GT plan missing", default_values

    try:
        limit_memory(3000)  # 3GB

        # Run the evaluation of the plan generated by the LLM
        # unique_id = f"{domain}__{model}_{task}__{inst_num}"
        baseline_plan = instance.get("baseline_donor")
        unique_id = f"{domain}__{model}_{task}__{inst_num}" + (f"__d{baseline_plan}" if baseline_plan is not None else "")

        curr_plan = re.sub(r'\bo(\d+)\b', r'object_\1', llm_plan) if "randomized" in domain else llm_plan
        if is_top_k_gt:
            gt_plans = get_gt_plans(domain, inst_num)
            chooser = ChooseGTPlan(curr_plan, gt_plans)
            chooser.choose_gt_plan_heuristic()
            gt_plan = chooser.get_gt_plan()
        else:
            gt_plan = optimal_gt_plan

        search_time_start = time.monotonic()
        evaluator = EvaluatePlanPerAction(curr_plan=curr_plan, optimal_gt_plan=optimal_gt_plan, gt_plan=gt_plan,
                                          validity=validity, domain=domain, instance_id=inst_num, unique_id=unique_id, search_params=search_params)
        evaluator.run_evaluation()
        search_time_end = time.monotonic()
        # print(f"Evaluator works, memory usage (MB) for inst {inst_num}:", psutil.Process(os.getpid()).memory_info().rss / 1024 ** 2)
        improver = InitialPlanRecovery(evaluator.curr_plan, evaluator, evaluator.gt_plan, domain, inst_num)

        # print(f"Improver works, memory usage (MB) for inst {inst_num}:", psutil.Process(os.getpid()).memory_info().rss / 1024 ** 2)

        plan_data = {
            "curr_plan": improver.curr_plan.get_plan(),
            "gt_plan": evaluator.gt_plan,
            "cdt_plan": improver.candidate_plan.get_plan(),
            "subseq_plan": improver.subseq_plan.get_plan(),
            "cdt_subseq_plan": improver.subseq_candidate_plan.get_plan(),
            "plan_trace": improver.curr_plan.plan_trace,
            "nr_plan_trace": improver.curr_plan.nr_plan_trace,
            "trace_score": improver.curr_plan.get_trace_score(),
            "complementary_plan": improver.complementary_plan,
            "correct_part": improver.correct_part,
            "final_score": evaluator.get_final_score(),
            "executable": improver.curr_plan.analysis["executable"]
        }

        result = {
            "curr_score": improver.curr_plan.get_score(),
            "curr_steps": len(improver.curr_plan.steps_to_validity),
            "curr_last_exec": improver.curr_plan.get_ind_last_exec(),
            "improved_plan": improver.improved_plan.get_plan(),

            "cdt_score": improver.candidate_plan.get_score(),
            "cdt_steps": len(improver.candidate_plan.steps_to_validity),
            "cdt_last_exec": improver.candidate_plan.get_ind_last_exec(),

            "subseq_score": improver.subseq_plan.get_score(),
            "subseq_steps": len(improver.subseq_plan.steps_to_validity),
            "subseq_last_exec": improver.subseq_plan.get_ind_last_exec(),

            "cdt_subseq_score": improver.subseq_candidate_plan.get_score(),
            "cdt_subseq_steps": len(improver.subseq_candidate_plan.steps_to_validity),
            "cdt_subseq_last_exec": improver.subseq_candidate_plan.get_ind_last_exec(),
        }

        validity = {
            "curr_validity": improver.curr_plan.is_valid,
            "cdt_validity": improver.candidate_plan.is_valid,
            "subseq_validity": improver.subseq_plan.is_valid,
            "cdt_subseq_validity": improver.subseq_candidate_plan.is_valid,
            "improved_validity": improver.improved_plan.is_valid,
        }

        running_example = True if domain == "blocksworld_3" and model == "gemma4-26b-a4b_it" and task == "_one_shot" and inst_num == 100 else False

        if running_example:
            running_example_jsons_dir = f"{current_dir}/running_example/json_dumps"
            os.makedirs(running_example_jsons_dir, exist_ok=True)
            improver.curr_plan.json_dump_plan_state(f"{running_example_jsons_dir}/plan_state_{unique_id}_curr_plan.json")
            improver.candidate_plan.json_dump_plan_state(f"{running_example_jsons_dir}/plan_state_{unique_id}_cdt_plan.json")
            improver.subseq_plan.json_dump_plan_state(f"{running_example_jsons_dir}/plan_state_{unique_id}_subseq_plan.json")
            improver.subseq_candidate_plan.json_dump_plan_state(f"{running_example_jsons_dir}/plan_state_{unique_id}_cdt_subseq_plan.json")
            improver.improved_plan.json_dump_plan_state(f"{running_example_jsons_dir}/plan_state_{unique_id}_improved_plan.json")

        print(f"Memory usage (MB) for inst {inst_num}:", psutil.Process(os.getpid()).memory_info().rss / 1024 ** 2)
        print(f"CPU usage (%) for inst {inst_num}:", psutil.Process(os.getpid()).cpu_percent(interval=1))
        # tmp_output_file = os.path.join(tmp_outputs_dir, f"{unique_id}.csv")

        search_time = search_time_end - search_time_start
        if plan_data is not None:
            # append_evaluation_to_csv(tmp_output_file, inst_num, plan_data, result, validity, params)
            # append_evaluation_to_csv(output_file, inst_num, plan_data, result, validity, params)
            row = get_row_for_csv(inst_num, plan_data, result, validity, params, search_params, search_time)
        else:
            row = default_values

        # Clear and return just status
        del evaluator, improver
        gc.collect()

        # Remove the plans in the plans directory that start with the unique_id
        base = f"plan_validation_{unique_id}"
        for filename in os.listdir(plans_dir):
            # if filename.startswith(f"plan_validation_{unique_id}"):
            if filename == f"{base}.txt" or filename.startswith(f"{base}_"):
                file_path = os.path.join(plans_dir, filename)
                if os.path.isfile(file_path):
                    os.remove(file_path)

        print(f"Instance {inst_num} processed successfully in {search_time:.2f} seconds.")

        return inst_num, True, "Processed successfully", row
    except MemoryError:
        print(f"MemoryError on instance {inst_num}")
        return inst_num, False, "MemoryError", default_values
    except Exception as e:
        print(f"Exception on instance {inst_num}: {e}")
        return inst_num, False, "Exception: " + str(e), default_values

def get_last_evaluated(output_file):
    """
    Get the last evaluated instance number from the output CSV file.
    If the file does not exist or is empty, return 0.
    """
    if not os.path.exists(output_file):
        return 0

    with open(output_file, "r", encoding="utf-8") as f:
        reader = csv.DictReader(f)
        instance_ids = [int(row["instance_id"]) for row in reader if row.get("instance_id")]

    return max(instance_ids) if instance_ids else 0

def get_unevaluated_instances(plans, output_file):
    """
    Get the sublist of instances that have not been evaluated yet based on the output CSV file.
    :param plans: the list of all instances
    :param output_file: the path to the evaluation CSV file
    :return: the list of instances that have not been evaluated yet
    """
    if not os.path.exists(output_file):
        return plans

    with open(output_file, "r", encoding="utf-8") as f:
        reader = csv.DictReader(f)
        evaluated_instance_ids = {int(row["instance_id"]) for row in reader if row.get("instance_id")}

    plans_to_evaluate = []
    for instance in plans:
        instance_id = instance.get("instance_id")
        if instance_id not in evaluated_instance_ids:
            plans_to_evaluate.append(instance)
    return plans_to_evaluate

def get_results_evaluated(output_file):
    """
    Get the number of unique instances (instance_id) that have been evaluated in the evaluation CSV file. If the evaluation file is None, return 0.
    :param evaluation_file: the path to the evaluation CSV file
    :return: the number of unique instances that have been evaluated
    """
    # TODO move to utils because it is used in summarise_results.py as well
    # If the evaluation file doesn't exist, return 0
    if not os.path.exists(output_file):
        print(f"Evaluation file {output_file} does not exist. Assuming 0 evaluations.")
        return 0

    with open(output_file, "r", encoding="utf-8") as f:
        reader = csv.DictReader(f)
        instance_ids = {row["instance_id"] for row in reader}

    return len(instance_ids)

def get_instance_timeout_per_domain(domain):
    """
    Get the timeout for processing an instance based on the domain.
    :param domain: the domain name
    :return: the timeout in seconds
    """
    timeouts = {
        "logistics": 900,  # 15 minutes
        "blocksworld": 600,  # 10 minutes
        "blocksworld_3": 300,  # 5 minutes
        "elevator": 1800,  # 30 minutes
        "satellite": 1800,  # 30 minutes
    }
    return timeouts.get(domain, 600)

def build_baseline_instances(domain, k, seed):
    instances = []
    for inst_id, donors in sorted(load_baseline_assignments(domain, k, seed).items(), key=lambda x: int(x[0])):
        for d in donors:
            plan = d["plan"]
            if isinstance(plan, list):
                plan = "\n".join(plan) + "\n"
            instances.append({"instance_id": int(inst_id), "extracted_llm_plan": plan, "ground_truth_plan": None, "llm_correct": False, "baseline_donor": d["donor_id"],})
    return instances

def get_unevaluated_baseline(instances, output_file):
    """Check per baseline plan rather than only per instance_id."""
    if not os.path.exists(output_file):
        return instances
    with open(output_file, "r", encoding="utf-8") as f:
        done = {(int(r["instance_id"]), int(r["baseline_donor"]))
                for r in csv.DictReader(f) if r.get("instance_id") and r.get("baseline_donor")}
    return [i for i in instances if (i["instance_id"], i["baseline_donor"]) not in done]

def worker_init():
    load_all_caches()


def main():
    # Argument parser
    parser = argparse.ArgumentParser(description="Run the full pipeline for evaluation of a plan generated by an LLM")
    parser.add_argument("--project", type=str, default="llm_planning_analysis", help="The project to evaluate the plan for")
    # RUNNING EXAMPLE
    # parser.add_argument("--domain", type=str, default="blocksworld_3", help="The domain to evaluate the plan for")
    # parser.add_argument("--model", type=str, default="gemma4-26b-a4b_it", help="The model to evaluate the plan for")
    # parser.add_argument("--task", type=str, default="", help="The task to evaluate the plan for", choices=["", "_state_tracking", "_pddl", "_zero_shot"])
    # parser.add_argument("--specific_instance", type=int, default=100, help="Specific instance number to process (if any)")
    parser.add_argument("--domain", type=str, default="logistics", help="The domain to evaluate the plan for")
    parser.add_argument("--model", type=str, default="claude-opus-4-8", help="The model to evaluate the plan for")
    parser.add_argument("--task", type=str, default="_pddl", help="The task to evaluate the plan for", choices=["", "_state_tracking", "_pddl", "_zero_shot"])
    parser.add_argument("--specific_instance", type=int, default=None, help="Specific instance number to process (if any)")
    parser.add_argument("--skip_existing", action="store_false", help="Skip instances that have already been processed")
    parser.add_argument("--top_k", type=int, default=3)
    parser.add_argument("--min_k", type=int, default=7)
    parser.add_argument("--max_k", type=int, default=25)
    parser.add_argument("--tol", type=float, default=0.1)
    parser.add_argument("--refine_iters", type=int, default=2)
    parser.add_argument("--baseline", action="store_true", help="Evaluate random same-length plans instead of LLM plans")
    parser.add_argument("--baseline_k", type=int, default=3)
    parser.add_argument("--baseline_seed", type=int, default=1)
    args = parser.parse_args()
    # configuration
    project = args.project  # llm_planning_analysis / plan-bench
    domain = args.domain # blocksworld_3, logistics
    model = args.model  # qwen, llama, qcode, llama_instruct, gemini_2_flash
    task = args.task  # "" -> "_one_shot", "_state_tracking", "_pddl", "_zero_shot"
    specific_instance = args.specific_instance  # None -> process all instances
    temp = 0.1
    top_p = 1
    params = set_configuration(model=model, task=task, domain=domain, project=project, temp=temp, top_p=top_p)
    search_params = dict(top_k=args.top_k, min_k=args.min_k, max_k=args.max_k, tol=args.tol, refine_iters=args.refine_iters)
    baseline = args.baseline

    if is_old_results:
        # filepath = f"{parent_dir}/LLM-Planning-PlanBench/{project}/results/{domain}/temp_{temp}_top_p_{top_p}/{model}/task_1_plan_generation{task}.json"
        filepath = f"{parent_dir}/LLM-Planning-PlanBench/{project}/results/{domain}/old_results/{model}/task_1_plan_generation{task}.json"
    else:
        filepath = f"{parent_dir}/LLM-Planning-PlanBench/{project}/results/{domain}/{model}/task_1_plan_generation{task}.json"

    if len(task) == 0:
        task = "_one_shot"
    # timestamp = time.strftime("%Y%m%d-%H%M%S")
    search_params_str = "_".join([f"{k}_{v}" for k, v in search_params.items()])
    output_file = f"{results_dir}/{domain}/{model}/evaluation_{task}.csv"  # _{search_params_str} plan_generation.csv
    if baseline:
        model = "baseline"
        output_file = f"{results_dir}/{domain}/baseline/evaluation_{task}_k{args.baseline_k}_seed{args.baseline_seed}.csv"

    os.makedirs(os.path.dirname(output_file), exist_ok=True)

    header = ["model", "domain", "task", "instance_id", "gt_plan", "curr_plan", "plan_trace", "nr_plan_trace", "trace_score", "complementary_plan", "correct_part", "executability",
              "final_score", "curr_score", "curr_steps", "curr_last_act", "curr_validity", "cdt_plan", "cdt_score", "cdt_steps", "cdt_last_act", "cdt_validity", "subseq_plan", "subseq_score", "subseq_steps", "subseq_last_act", "subseq_validity", "cdt_subseq_plan", "cdt_subseq_score", "cdt_subseq_steps", "cdt_subseq_last_act", "cdt_subseq_validity",
              "improved_plan", "improved_validity", "cfg_top_k", "cfg_min_k", "cfg_max_k", "cfg_tol", "cfg_refine_iters", "search_time", "baseline_donor"]
    header_written: bool = os.path.exists(output_file) and os.path.getsize(output_file) > 0

    skip_existing = args.skip_existing
    offset = 1 if task == "_zero_shot" else 0

    if not baseline:
        try:
            # Get all instances for this configuration
            plans = get_plans_from_json(filepath)
        except FileNotFoundError:
            print(f"Configuration does not exist / File Not Found: {filepath}")
            return
    else:
        all_instances = build_baseline_instances(domain, args.baseline_k, args.baseline_seed)
        plans_to_evaluate = get_unevaluated_baseline(all_instances, output_file) if skip_existing else all_instances
        plans = all_instances
        print(f"Baseline: {len(plans_to_evaluate)} (instance, baseline_plan) pairs to evaluate.")
        if not plans_to_evaluate:
            return

    last_evaluated_instance = get_last_evaluated(output_file)

    validate = True
    filename = "valid_plans.json" if validate else "gt_plans.json"
    gt_file_path = os.path.join(os.pardir, os.pardir, "results/gt_plans", domain, filename)
    if not os.path.exists(gt_file_path):
        # If the file does not exist, generate the ground truth plans for this domain
        print(
            f"Ground truth plans file not found: {gt_file_path} for domain {domain}. Generating ground truth plans, this may take a while...")
        generated_plans, valid_plans = generate_gt_plans(domain, validate=validate, generate=True, max_instances=101)

    max_workers = os.cpu_count() * 1 // 2  # 2 // 3
    print("CONCURRENCY: max workers are", max_workers)

    instance_timeout = get_instance_timeout_per_domain(domain)
    overall_timeout = instance_timeout * len(plans) * 2 / 3  # was 3 * 3600
    start_time = time.monotonic()

    begin = 0 # if not skip_existing else max(min(last_evaluated + offset - 1, len(plans)), 0)
    end = min(len(plans), 100) if not baseline else min(len(plans), 300) # k=3
    plans_to_evaluate = get_unevaluated_instances(plans[begin:end], output_file) if skip_existing else plans[begin:end]

    if specific_instance is not None:
        begin = specific_instance + offset - 2
        end = begin + 1
        if begin < 0 or begin >= len(plans):
            print(f"Specific instance {specific_instance} is out of range for domain {domain}.")
            return
        plans_to_evaluate = plans[begin:end]
        print(f"Processing specific instance {specific_instance} for {domain}, {model}, {task}.")
    else:
        print(
            f"Evaluating {len(plans_to_evaluate)} instances for {domain}, {model}, {task}; last evaluated instance: {last_evaluated_instance + 1}.")
        if len(plans_to_evaluate) == 0:
            print(f"All instances have been processed for {domain}, {model}, {task}.")
            print(f"File {output_file} has {get_results_evaluated(output_file)} evaluated instances.")
            return
        elif len(plans_to_evaluate) < 10 or last_evaluated_instance > 99:
            print(f"WARNING: Only {len(plans_to_evaluate)} instances to evaluate for {domain}, {model}, {task} and last evaluates {last_evaluated_instance}. Skipping for now.")
            return

    with ProcessPool(max_workers=max_workers, initializer=worker_init) as pool:
        futures = {}
        for instance in plans_to_evaluate:
            elapsed = time.monotonic() - start_time
            if elapsed > overall_timeout:
                print(f"Overall timeout ({overall_timeout}s) reached after submitting "
                      f"{len(futures)} instances. Stopping further submission.")
                break

            instance_id = instance.get("instance_id")
            baseline_plan = instance.get("baseline_donor") if baseline else None

            future = pool.schedule(
                profile_process_instance,
                kwargs=dict(instance=instance, task=task, domain=domain,
                            model=model, params=params, search_params=search_params),
                timeout=instance_timeout
            )
            if baseline:
                print(f"Submitted instance {instance_id} with baseline donor {baseline_plan} for evaluation.")
                futures[future] = (instance_id, baseline_plan)
            else:
                futures[future] = instance_id

        for future in as_completed(futures):
            if baseline:
                instance_id, baseline_plan = futures[future]
            else:
                instance_id = futures[future]
            remaining_time = max(overall_timeout - (time.monotonic() - start_time), 0)
            try:
                inst_id, is_processed, reason, row_data = future.result(timeout=min(instance_timeout, remaining_time) or 0.1)
                label = f"{inst_id}" + (f" (donor {baseline_plan})" if baseline else "")
                if not is_processed and reason != "LLM plan missing":
                    print(f"WARNING: instance {label} failed to process. Reason: {reason}")
                else:
                    if reason == "LLM plan missing":
                        print(f"Instance {label} has missing LLM plan. Adding default values.")
                    else:
                        print(f"Instance {label} processed successfully.")
                    with open(output_file, "a", newline="") as csv_file:
                        writer = csv.writer(csv_file)
                        if not header_written:
                            writer.writerow(header)
                            header_written = True
                        if baseline:
                            row_data = list(row_data) + [baseline_plan]
                        writer.writerow(row_data)
            except PebbleTimeoutError:
                print(f"Timeout on instance {label}. Moving on...")
            except Exception as e:
                print(f"Error occurred in instance {label}: {str(e)}")

    merge_worker_caches()
    # write_evaluation_to_csv(output_file, plans_res, curr_scores, params, curr_validity)

    # Remove the plans directory after processing
    for filename in os.listdir(plans_dir):
        file_path = os.path.join(plans_dir, filename)
        if os.path.isfile(file_path):
            os.remove(file_path)

if __name__ == "__main__":
    main()
